def is_palindrome(s):
    return s == s[::-1]

def palindrome_degree(s):
    n = len(s)
    if n == 0:
        return 0
    if n == 1:
        return 1

    if is_palindrome(s):
        return 1 + palindrome_degree(s[1:-1])
    else:
        return 0

def sum_of_palindrome_degrees(s):
    total_sum = 0
    for i in range(1, len(s) + 1):
        total_sum += palindrome_degree(s[:i])
    return total_sum

